/// <summary>
/// CB395_CSDFulfilementInterBranchTransfer.
/// Class responsible for creating CSD transfer orders catering for scenario having one to one mapping.
/// </summary>
class METCreateCSDTransferOrder_BulkTransferForSO extends METCreateCSDTransferOrder
{
    Map groupingMap,
        salesIdTOmap,
        salesIdStagingLaneMap;

}

Method.Source:
/// <summary>
/// Gets grouping map key.
/// </summary>
/// <returns>Grouping map key.</returns>
private container getGroupingKey()
{
    return [salesLine.ItemId, 
            salesLine.SalesUnit, 
            metSalesLine.SupplyingWarehouse,
            salestable.InventLocationId];
}

/// <summary>
/// Sets grouping map key.
/// </summary>
/// <param name = "_key">Grouping may key.</param>
private void setFromKeyValue(container _key)
{
    [salesLine.ItemId,
     salesLine.SalesUnit,
     metSalesLine.SupplyingWarehouse,
     salestable.InventLocationId] = _key;
}

/// <summary>
/// Gets grouping map value.
/// </summary>
/// <returns>Grouping map value.</returns>
private container getGroupingValue()
{
    return [transferTable,
            transferLine,
            salesLine,
            salesTable];  
}

/// <summary>
/// Sets grouping map value.
/// </summary>
/// <param name = "_value">Grouping map value.</param>
private void setFromGroupingValue(container _value)
{
    [transferTable,
     transferLine,
     salesLine,
     salesTable] = _value;

    metTransferTable = transferTable.metInventTransferTableExt();
    metTransferLine  = transferLine.metInventTransferLine();
}

/// <summary>
/// Initialzes variables.
/// </summary>
protected void init()
{
    super();

    groupingMap = new Map(Types::Container, Types::Container);

    if (doSetStagingLane)
    {
        salesIdTOmap = new Map(Types::Container, Types::Class);
        salesIdStagingLaneMap = new Map(Types::Class, Types::String);
    }
}

/// <summary>
/// Initializes transfer order records.
/// </summary>
protected void initTransferOrder()
{
    if (doSetStagingLane)
    {
        this.addToSalesIdTOmap(this.getGroupingKey(), salestable.SalesId);
    }

    if (groupingMap.exists(this.getGroupingKey()))
    {
        container value;
        SalesQty  qty;

        qty = salesLine.SalesQty;
        value = groupingMap.lookup(this.getGroupingKey());
        this.setFromGroupingValue(value);

        transferLine.QtyTransfer += qty;
    }
    else
    {
        super();
    }

    groupingMap.insert(this.getGroupingKey(), this.getGroupingValue());
}

/// <summary>
/// Adds sales id(s) into transfer orders map.
/// </summary>
/// <param name = "_key">Container containing key.</param>
/// <param name = "_salesId">Sales Id(s).</param>
protected void addToSalesIdTOmap(container _key, SalesId _salesId)
{
    Set salesIdSet;

    if (salesIdTOmap.exists(_key))
    {
        salesIdSet = salesIdTOmap.lookup(_key);
    }
    else
    {
        salesIdSet = new Set(Types::String);
    }

    salesIdSet.add(_salesId);
    salesIdTOmap.insert(_key, salesIdSet);
}

/// <summary>
/// Initalizes records.
/// </summary>
protected void initRecords()
{
    super();

    this.addGroupedRecords();
}

/// <summary>
/// Adds grouped records to transfer order map.
/// </summary>
private void addGroupedRecords()
{
    MapEnumerator mapEnum;
    container     key, value;

    mapEnum = groupingMap.getEnumerator() as MapEnumerator;

    while (mapEnum && mapEnum.moveNext())
    {
        key = mapEnum.currentKey();
        value = mapEnum.currentValue();

        this.setFromKeyValue(key);
        this.setFromGroupingValue(value);
        this.applyRules();
        this.addToTransferOrderMap();
    }
}

/// <summary>
/// Applies route rule.
/// </summary>
/// <param name = "_apply">Rule to apply.</param>
protected void applyRouteRule(METFulfilmentRuleApply _apply)
{
    super(_apply);

    if (_apply == METFulfilmentRuleApply::InternalTORoute
    &&  metTransferTable.InternalCustomer
    &&  metTransferTable.StagingLane
    &&  doSetStagingLane)
    {
        if (salesIdTOmap.exists(this.getGroupingKey()))
        {
            Set salesIdSet = salesIdTOmap.lookup(this.getGroupingKey());

            salesIdStagingLaneMap.insert(salesIdSet, metTransferTable.StagingLane);
        }
    }

}

/// <summary>
/// Updates staging lane.
/// </summary>
protected void updateStagingLane()
{
    void update(Set _salesIdSet, METStagingLaneId _stagingLane)
    {
        SetEnumerator setEnum = _salesIdSet.getEnumerator();

        while (setEnum && setEnum.moveNext())
        {
            SalesId salesId = setEnum.current();

            ttsbegin;

            METSalesTable metSalesTableUpdate;

            metSalesTableUpdate.readPast(true);

            metSalesTableUpdate = METSalesTable::findBySalesId(salesId, true);

            if (metSalesTableUpdate)
            {
                metSalesTableUpdate.StagingLaneId = _stagingLane;
                metSalesTableUpdate.update();
            }

            ttscommit;
        }
    }

    MapEnumerator mapEnum;

    mapEnum = salesIdStagingLaneMap.getEnumerator();

    while (mapEnum && mapEnum.moveNext())
    {
        Set salesIdSet = mapEnum.currentKey();
        METStagingLaneId stagingLane = mapEnum.currentValue();

        update(salesIdSet, stagingLane);
    }

}
